package com.vault.entity;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="api_keys",indexes={@Index(name="idx_keys_owner",columnList="user_id"),@Index(name="idx_keys_status",columnList="status")}) public class ApiKey{
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user;@Column(name="service_name",nullable=false,length=60) private String serviceName;@Column(name="key_name",nullable=false,length=120) private String keyName;@Column(name="encrypted_key",nullable=false,length=2048) private String encryptedKey;@Column(nullable=false,length=20) private String environment;@Column(length=500) private String description;@Column(nullable=false,length=20) private String status="ACTIVE";@Column(name="expires_at") private Instant expiresAt;@Column(name="created_at",nullable=false) private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now();@Column(name="last_used_at") private Instant lastUsedAt;protected ApiKey(){}public ApiKey(User u,String s,String n,String k,String e,String d,Instant x){user=u;serviceName=s;keyName=n;encryptedKey=k;environment=e;description=d;expiresAt=x;}@PreUpdate void touch(){updatedAt=Instant.now();}public String effectiveStatus(){return "ACTIVE".equals(status)&&expiresAt!=null&&expiresAt.isBefore(Instant.now())?"EXPIRED":status;}public UUID getId(){return id;}public User getUser(){return user;}public String getServiceName(){return serviceName;}public void setServiceName(String x){serviceName=x;}public String getKeyName(){return keyName;}public void setKeyName(String x){keyName=x;}public String getEncryptedKey(){return encryptedKey;}public void setEncryptedKey(String x){encryptedKey=x;}public String getEnvironment(){return environment;}public void setEnvironment(String x){environment=x;}public String getDescription(){return description;}public void setDescription(String x){description=x;}public String getStatus(){return status;}public void setStatus(String x){status=x;}public Instant getExpiresAt(){return expiresAt;}public void setExpiresAt(Instant x){expiresAt=x;}public Instant getCreatedAt(){return createdAt;}public Instant getLastUsedAt(){return lastUsedAt;}public void setLastUsedAt(Instant x){lastUsedAt=x;}}
